-- 096_payment_retention.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_payment_retention_terms(
 id uuid PRIMARY KEY,payment_schedule_id uuid NOT NULL UNIQUE REFERENCES public.project_payment_schedules(id)ON DELETE RESTRICT,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,retention_percentage numeric(8,4)NOT NULL CHECK(retention_percentage>0 AND retention_percentage<=20),release_condition text NOT NULL CHECK(btrim(release_condition)<>''AND char_length(release_condition)<=2000),status text NOT NULL CHECK(status IN('ACTIVE','RELEASED')),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz
);
CREATE TABLE IF NOT EXISTS public.project_payment_retention_releases(
 id uuid PRIMARY KEY,retention_terms_id uuid NOT NULL UNIQUE REFERENCES public.project_payment_retention_terms(id)ON DELETE RESTRICT,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,released_amount numeric(24,2)NOT NULL CHECK(released_amount>0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),external_reference text NOT NULL CHECK(btrim(external_reference)<>''AND char_length(external_reference)<=500),release_date date NOT NULL,release_note text NOT NULL CHECK(char_length(release_note)<=3000),released_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,recorded_at timestamptz NOT NULL DEFAULT now()
);
CREATE OR REPLACE FUNCTION private.prevent_payment_retention_release_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PAYMENT_RETENTION_RELEASE_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS payment_retention_release_immutable ON public.project_payment_retention_releases;CREATE TRIGGER payment_retention_release_immutable BEFORE UPDATE OR DELETE ON public.project_payment_retention_releases FOR EACH ROW EXECUTE FUNCTION private.prevent_payment_retention_release_mutation();
ALTER TABLE public.project_payment_retention_terms ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_payment_retention_releases ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS payment_retention_terms_select ON public.project_payment_retention_terms;DROP POLICY IF EXISTS payment_retention_releases_select ON public.project_payment_retention_releases;CREATE POLICY payment_retention_terms_select ON public.project_payment_retention_terms FOR SELECT TO authenticated USING(public.can_access_project(project_id));CREATE POLICY payment_retention_releases_select ON public.project_payment_retention_releases FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_payment_retention_terms,public.project_payment_retention_releases FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_retention_terms,public.project_payment_retention_releases TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_payment_retention_terms(p_payment_schedule_id uuid,p_terms_id uuid,p_retention_percentage numeric,p_release_condition text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO s FROM public.project_payment_schedules WHERE id=p_payment_schedule_id FOR UPDATE;IF s.id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(s.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_RETENTION_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_terms_id IS NULL OR p_client_request_id IS NULL OR COALESCE(p_retention_percentage,0)<=0 OR p_retention_percentage>20 OR btrim(COALESCE(p_release_condition,''))=''OR char_length(p_release_condition)>2000 OR s.status<>'ACTIVE'THEN RAISE EXCEPTION'INVALID_PAYMENT_RETENTION_TERMS'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_retention.save_terms',p_client_request_id,s.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_retention.save_terms'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id WHERE m.payment_schedule_id=s.id)THEN RAISE EXCEPTION'RETENTION_TERMS_LOCKED_AFTER_CERTIFICATION_START'USING ERRCODE='55000';END IF;INSERT INTO public.project_payment_retention_terms VALUES(p_terms_id,s.id,s.project_id,p_retention_percentage,btrim(p_release_condition),'ACTIVE',u,now(),NULL);result:=jsonb_build_object('retentionTermsId',p_terms_id,'status','ACTIVE','retentionPercentage',p_retention_percentage,'releaseCondition',btrim(p_release_condition));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.release_project_payment_retention(p_payment_schedule_id uuid,p_release_id uuid,p_external_reference text,p_release_date date,p_release_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;s public.project_payment_schedules%ROWTYPE;t public.project_payment_retention_terms%ROWTYPE;req public.write_command_requests%ROWTYPE;total numeric;case_count integer;unpaid_count integer;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO s FROM public.project_payment_schedules WHERE id=p_payment_schedule_id;SELECT *INTO t FROM public.project_payment_retention_terms WHERE payment_schedule_id=s.id FOR UPDATE;IF t.id IS NULL THEN RAISE EXCEPTION'PAYMENT_RETENTION_TERMS_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(s.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_RETENTION_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_release_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_external_reference,''))=''OR p_release_date IS NULL OR char_length(COALESCE(p_release_note,''))>3000 THEN RAISE EXCEPTION'INVALID_PAYMENT_RETENTION_RELEASE'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_retention.release',p_client_request_id,s.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_retention.release'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF t.status<>'ACTIVE'THEN RAISE EXCEPTION'INVALID_PAYMENT_RETENTION_RELEASE'USING ERRCODE='22023';END IF;SELECT count(*),count(*)FILTER(WHERE c.status<>'PAID'),COALESCE(sum(round(d.certified_amount*t.retention_percentage/100,2)),0)INTO case_count,unpaid_count,total FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN LATERAL(SELECT certified_amount FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1)d ON true WHERE m.payment_schedule_id=s.id;IF case_count=0 OR unpaid_count>0 OR total<=0 THEN RAISE EXCEPTION'RETENTION_RELEASE_REQUIRES_ALL_CERTIFIED_CASES_PAID'USING ERRCODE='55000';END IF;INSERT INTO public.project_payment_retention_releases VALUES(p_release_id,t.id,s.project_id,total,s.currency_code,btrim(p_external_reference),p_release_date,btrim(COALESCE(p_release_note,'')),u,now());UPDATE public.project_payment_retention_terms SET status='RELEASED',released_at=now()WHERE id=t.id;result:=jsonb_build_object('retentionReleaseId',p_release_id,'status','RELEASED','releasedAmount',total,'currencyCode',s.currency_code);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
COMMIT;
BEGIN;
CREATE OR REPLACE FUNCTION public.record_payment_tracking_event(p_certification_case_id uuid,p_event_id uuid,p_event_type text,p_amount numeric,p_external_reference text,p_event_date date,p_event_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;c public.project_payment_certification_cases%ROWTYPE;m public.project_payment_milestones%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;kind text:=upper(btrim(COALESCE(p_event_type,'')));certified numeric;retention_pct numeric:=0;retention_amount numeric:=0;payable numeric;paid_before numeric;paid_after numeric;event_no integer;next_status text;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO c FROM public.project_payment_certification_cases WHERE id=p_certification_case_id FOR UPDATE;IF c.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_CASE_NOT_FOUND'USING ERRCODE='P0002';END IF;SELECT *INTO m FROM public.project_payment_milestones WHERE id=c.milestone_id FOR UPDATE;SELECT *INTO s FROM public.project_payment_schedules WHERE id=m.payment_schedule_id;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(c.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_TRACKING_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_event_id IS NULL OR p_client_request_id IS NULL OR kind NOT IN('SENT_FOR_PAYMENT','PAYMENT_RECEIVED')OR COALESCE(p_amount,0)<=0 OR btrim(COALESCE(p_external_reference,''))=''OR char_length(p_external_reference)>500 OR p_event_date IS NULL OR char_length(COALESCE(p_event_note,''))>3000 THEN RAISE EXCEPTION'INVALID_PAYMENT_TRACKING_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_tracking.record',p_client_request_id,c.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_tracking.record'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;SELECT certified_amount INTO certified FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1;IF certified IS NULL THEN RAISE EXCEPTION'PAYMENT_REQUIRES_CERTIFIED_AMOUNT'USING ERRCODE='55000';END IF;SELECT COALESCE(retention_percentage,0)INTO retention_pct FROM public.project_payment_retention_terms WHERE payment_schedule_id=s.id;retention_amount:=round(certified*retention_pct/100,2);payable:=certified-retention_amount;SELECT COALESCE(sum(amount),0)INTO paid_before FROM public.project_payment_tracking_events WHERE certification_case_id=c.id AND event_type='PAYMENT_RECEIVED';IF kind='SENT_FOR_PAYMENT'AND(c.status NOT IN('APPROVED','PARTIALLY_APPROVED')OR p_amount<>payable OR EXISTS(SELECT 1 FROM public.project_payment_tracking_events WHERE certification_case_id=c.id AND event_type='SENT_FOR_PAYMENT'))THEN RAISE EXCEPTION'INVALID_SEND_FOR_PAYMENT_STATE_OR_NET_AMOUNT'USING ERRCODE='55000';ELSIF kind='PAYMENT_RECEIVED'AND(c.status<>'SENT_FOR_PAYMENT'OR paid_before+p_amount>payable)THEN RAISE EXCEPTION'INVALID_PAYMENT_RECEIPT_STATE_OR_NET_AMOUNT'USING ERRCODE='55000';END IF;SELECT COALESCE(max(event_number),0)+1 INTO event_no FROM public.project_payment_tracking_events WHERE certification_case_id=c.id;INSERT INTO public.project_payment_tracking_events VALUES(p_event_id,c.id,c.project_id,event_no,kind,p_amount,s.currency_code,btrim(p_external_reference),p_event_date,btrim(COALESCE(p_event_note,'')),u,now());paid_after:=paid_before+CASE WHEN kind='PAYMENT_RECEIVED'THEN p_amount ELSE 0 END;next_status:=CASE WHEN kind='SENT_FOR_PAYMENT'THEN'SENT_FOR_PAYMENT'WHEN paid_after=payable THEN'PAID'ELSE'SENT_FOR_PAYMENT'END;UPDATE public.project_payment_certification_cases SET status=next_status WHERE id=c.id;UPDATE public.project_payment_milestones SET status=next_status WHERE id=m.id;result:=jsonb_build_object('eventId',p_event_id,'eventNumber',event_no,'eventType',kind,'caseStatus',next_status,'certifiedAmount',certified,'retentionAmount',retention_amount,'payableAmount',payable,'paidAmount',paid_after,'outstandingAmount',payable-paid_after,'currencyCode',s.currency_code);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_payment_tracking(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_TRACKING_FORBIDDEN'USING ERRCODE='42501';END IF;RETURN jsonb_build_object('projectId',p_project_id,'payments',COALESCE((SELECT jsonb_agg(jsonb_build_object('certificationCaseId',c.id,'caseNumber',c.case_number,'caseStatus',c.status,'milestoneTitle',m.title,'currencyCode',s.currency_code,'certifiedAmount',d.certified_amount,'retentionAmount',round(d.certified_amount*COALESCE(t.retention_percentage,0)/100,2),'payableAmount',d.certified_amount-round(d.certified_amount*COALESCE(t.retention_percentage,0)/100,2),'paidAmount',COALESCE(x.paid_amount,0),'outstandingAmount',d.certified_amount-round(d.certified_amount*COALESCE(t.retention_percentage,0)/100,2)-COALESCE(x.paid_amount,0),'events',COALESCE(x.events,'[]'::jsonb))ORDER BY c.case_number DESC)FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN public.project_payment_schedules s ON s.id=m.payment_schedule_id LEFT JOIN public.project_payment_retention_terms t ON t.payment_schedule_id=s.id JOIN LATERAL(SELECT certified_amount FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1)d ON true LEFT JOIN LATERAL(SELECT sum(amount)FILTER(WHERE event_type='PAYMENT_RECEIVED')paid_amount,jsonb_agg(jsonb_build_object('eventId',id,'eventNumber',event_number,'eventType',event_type,'amount',amount,'externalReference',external_reference,'eventDate',event_date,'eventNote',event_note,'recordedAt',recorded_at)ORDER BY event_number)events FROM public.project_payment_tracking_events WHERE certification_case_id=c.id)x ON true WHERE c.project_id=p_project_id),'[]'::jsonb));END;$$;
CREATE OR REPLACE FUNCTION public.get_project_payment_retention(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE s public.project_payment_schedules%ROWTYPE;t public.project_payment_retention_terms%ROWTYPE;held numeric:=0;released numeric:=0;case_count integer:=0;unpaid_count integer:=0;
BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_RETENTION_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id AND status='ACTIVE';IF s.id IS NULL THEN RETURN jsonb_build_object('projectId',p_project_id,'hasTerms',false,'canConfigure',false);END IF;SELECT *INTO t FROM public.project_payment_retention_terms WHERE payment_schedule_id=s.id;IF t.id IS NULL THEN RETURN jsonb_build_object('projectId',p_project_id,'paymentScheduleId',s.id,'hasTerms',false,'canConfigure',NOT EXISTS(SELECT 1 FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id WHERE m.payment_schedule_id=s.id));END IF;SELECT count(*),count(*)FILTER(WHERE c.status<>'PAID'),COALESCE(sum(round(d.certified_amount*t.retention_percentage/100,2)),0)INTO case_count,unpaid_count,held FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN LATERAL(SELECT certified_amount FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1)d ON true WHERE m.payment_schedule_id=s.id;SELECT COALESCE(released_amount,0)INTO released FROM public.project_payment_retention_releases WHERE retention_terms_id=t.id;RETURN jsonb_build_object('projectId',p_project_id,'paymentScheduleId',s.id,'hasTerms',true,'retentionTermsId',t.id,'status',t.status,'retentionPercentage',t.retention_percentage,'releaseCondition',t.release_condition,'heldAmount',held,'releasedAmount',released,'outstandingRetention',held-released,'currencyCode',s.currency_code,'canRelease',t.status='ACTIVE'AND case_count>0 AND unpaid_count=0 AND held>0);END;$$;
REVOKE ALL ON FUNCTION private.prevent_payment_retention_release_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_payment_retention_terms(uuid,uuid,numeric,text,uuid),public.release_project_payment_retention(uuid,uuid,text,date,text,uuid),public.get_project_payment_retention(bigint),public.record_payment_tracking_event(uuid,uuid,text,numeric,text,date,text,uuid),public.get_project_payment_tracking(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_payment_retention_terms(uuid,uuid,numeric,text,uuid),public.release_project_payment_retention(uuid,uuid,text,date,text,uuid),public.get_project_payment_retention(bigint),public.record_payment_tracking_event(uuid,uuid,text,numeric,text,date,text,uuid),public.get_project_payment_tracking(bigint)TO authenticated;
COMMIT;
